from z3 import *

# Social Golfers problem: 18 golfers, 7 weeks, 6 groups of 3
num_golfers = 18
num_weeks = 7
num_groups = 6
group_size = 3

# Create variables: group[w][p] = group assignment for golfer p in week w
group = [[Int(f'g_{w}_{p}') for p in range(num_golfers)] for w in range(num_weeks)]

solver = Optimize()

# Constraint 1: Each golfer is assigned to a valid group (0-5)
for w in range(num_weeks):
    for p in range(num_golfers):
        solver.add(group[w][p] >= 0, group[w][p] < num_groups)

# Constraint 2: Each week, each group has exactly 3 golfers
for w in range(num_weeks):
    for g in range(num_groups):
        solver.add(Sum([If(group[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

# Constraint 3: No pair of golfers is in the same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1 + 1, num_golfers):
        # Count how many weeks p1 and p2 are in the same group
        same_group_count = Sum([If(group[w][p1] == group[w][p2], 1, 0) for w in range(num_weeks)])
        solver.add(same_group_count <= 1)

# Try to solve
print("Solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            solution.append(m[group[w][p]].as_long())
    print(f"Solution: {solution}")

    # Verify the solution
    print("\nVerifying solution...")
    # Check each week has valid groups
    for w in range(num_weeks):
        groups = {}
        for p in range(num_golfers):
            g = solution[w * num_golfers + p]
            if g not in groups:
                groups[g] = []
            groups[g].append(p)
        for g in range(num_groups):
            if g not in groups or len(groups[g]) != group_size:
                print(f"Week {w}, group {g} has {len(groups.get(g, []))} golfers")

    # Check no pair appears twice
    pair_count = {}
    for w in range(num_weeks):
        for g in range(num_groups):
            golfers_in_group = [p for p in range(num_golfers) if solution[w * num_golfers + p] == g]
            for i in range(len(golfers_in_group)):
                for j in range(i + 1, len(golfers_in_group)):
                    pair = (min(golfers_in_group[i], golfers_in_group[j]), max(golfers_in_group[i], golfers_in_group[j]))
                    if pair in pair_count:
                        print(f"Pair {pair} appears in weeks {pair_count[pair]} and {w}")
                    pair_count[pair] = w

    print(f"Total pairs used: {len(pair_count)} out of {num_golfers * (num_golfers - 1) // 2}")
else:
    print("UNSATISFIABLE")

